  assert.equal(monthlyCents({ price: 12000, cycle: 'yearly' }), 1000);
  assert.equal(monthlyCents({ price: 11999, cycle: 'yearly' }), 1000);
  assert.equal(monthlyCents({ price: 1450, cycle: 'yearly' }), 121);
});

test('a weekly plan costs its price x 52 / 12 a month, rounded to the nearest cent', () => {
  assert.equal(monthlyCents({ price: 1200, cycle: 'weekly' }), 5200);
  assert.equal(monthlyCents({ price: 5990, cycle: 'weekly' }), 25957);
});

test('weekly plans charge every 7 days from their first charge', () => {
  const sub = { cycle: 'weekly', since: '2026-10-01' };
  assert.equal(nextCharge(sub, '2026-10-01'), '2026-10-01');
  assert.equal(nextCharge(sub, '2026-10-02'), '2026-10-08');
  assert.equal(nextCharge(sub, '2026-10-24'), '2026-10-29');
  assert.equal(nextCharge(sub, '2026-09-20'), '2026-10-01');
  assert.equal(nextCharge({ cycle: 'weekly', since: '2026-12-28' }, '2027-01-05'), '2027-01-11');
});

